def calc(expr: str) -> int | str:
    # Tokenize
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif expr[i] in '+-*/%^()':
            tokens.append(('op', expr[i]))
            i += 1
        else:
            i += 1

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_primary():
        t = peek()
        if t[0] == 'num':
            consume()
            return t[1]
        elif t[1] == '(':
            consume()
            val = parse_expr()
            consume()  # ')'
            return val
        return None

    def parse_unary():
        count = 0
        while peek() and peek()[0] == 'op' and peek()[1] == '-':
            consume()
            count += 1
        val = parse_power()
        if val == "error":
            return "error"
        return val if count % 2 == 0 else -val

    def parse_power():
        left = parse_primary()
        if left == "error":
            return "error"
        if peek() and peek()[0] == 'op' and peek()[1] == '^':
            consume()
            right = parse_unary()
            if right == "error":
                return "error"
            if right < 0:
                return "error"
            if right == 0:
                left = 1
            else:
                left = left ** right
        return left

    def parse_mul():
        left = parse_unary()
        if left == "error":
            return "error"
        while peek() and peek()[0] == 'op' and peek()[1] in '*/%':
            op = consume()[1]
            right = parse_unary()
            if right == "error":
                return "error"
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    return "error"
                left = int(left / right)
            elif op == '%':
                if right == 0:
                    return "error"
                left = left - right * int(left / right)
        return left

    def parse_expr():
        left = parse_mul()
        if left == "error":
            return "error"
        while peek() and peek()[0] == 'op' and peek()[1] in '+-':
            op = consume()[1]
            right = parse_mul()
            if right == "error":
                return "error"
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    result = parse_expr()
    return result
